// The shared fee schedule vectors: regenerated byte for byte, then replayed through the reducer.
// WRITE_FEE_VECTORS=1 refreshes docs/native/vectors/fee-schedule.json after a reviewed change.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  NativeIndexer, checkRate, checkRules, decode, decodeOptions, fee, feeKept, fromHex, TICKERS_DIGEST,
} from '../../../packages/native/src/index.ts';
import { snapshot, snapshotState, stateRoot, verifiedFeeSchedule } from '../src/pq/checkpoint.ts';
import { generateVectors, parseVectors, randomHistory, toJson, vectorsText } from './helpers/fee-schedule-vectors.mjs';
import { unactivatedMainnet } from '../../../packages/native/test/helpers/activated-mainnet.mjs';

// The release pins the mainnet activation: mainnet cases recorded before it replay on the reader
// with both pins null.
const unactivated = await unactivatedMainnet();
test.after(unactivated.close);

const FILE = resolve(dirname(fileURLToPath(import.meta.url)), '../../../docs/native/vectors/fee-schedule.json');
/** Block JSON back to reducer input: amounts and nonces are bigints again. */
const block = (b) => ({
  ...b,
  receipts: b.receipts.map((r) => ({
    ...r,
    events: r.events.map((e) =>
      e.kind === 'paid' ? { ...e, amount: BigInt(e.amount) } : e.kind === 'multisig' && e.nonce !== undefined ? { ...e, nonce: BigInt(e.nonce) } : e,
    ),
  })),
});
const replay = (c, check = () => {}) => {
  const rules = checkRules(c.rules);
  const Indexer = c.genesis === unactivated.lib.MAINNET ? unactivated.lib.NativeIndexer : NativeIndexer;
  const x = new Indexer(c.genesis, c.activation, false, rules);
  for (const b of c.blocks) {
    x.apply(block(b));
    check(x, b, rules);
  }
  return x;
};

const text = vectorsText();
test('the vectors file is exactly what the generator produces', () => {
  if (process.env.WRITE_FEE_VECTORS === '1') {
    mkdirSync(dirname(FILE), { recursive: true });
    writeFileSync(FILE, text);
  }
  assert.equal(readFileSync(FILE, 'utf8'), text);
  assert.equal(vectorsText(generateVectors()), text, 'deterministic');
});

const v = parseVectors(text);
for (const c of v.cases)
  test(`replay: ${c.name}`, () => {
    const verdicts = [], roots = [];
    const wanted = new Set(c.expect.roots.map((r) => r.height));
    replay(c, (x, b, rules) => {
      const s = x.state();
      for (const r of b.receipts) {
        const j = s.journal.find((e) => e.height === b.height && e.index === r.index);
        const verdict = j ? j.verdict : null;
        verdicts.push({ height: b.height, index: r.index, verdict, feeKept: feeKept(block(b).receipts.find((y) => y.index === r.index), verdict, rules, b.height) });
      }
      if (wanted.has(b.height)) {
        const snap = snapshot(s, c.genesis);
        roots.push({ height: b.height, stateRoot: stateRoot(snap) });
        // Format 2 snapshots read back to the same state, fee state included.
        if (s.fees) assert.deepEqual(snapshotState(snap, c.genesis, true).fees, s.fees);
      }
    });
    assert.deepEqual(verdicts, c.expect.verdicts);
    assert.deepEqual(roots, c.expect.roots);
  });

test('the vectors cover every verdict of the fee rule and of governance', () => {
  const seen = new Set(v.cases.flatMap((c) => c.expect.verdicts.map((r) => r.verdict)));
  for (const verdict of [
    'symbol blocked', 'fee does not match the fee schedule', 'fee schedule not active',
    'fee batch must be exactly remark_with_event + transfer to Qlyphs', 'fee batch receipt does not show the paid Qlyphs fee',
    'fee schedule requires a direct remark_with_event', 'fee operator frozen', 'not the fee operator', 'invalid effective height',
    'rate out of bounds', 'rate not canonical', 'rate step too large', 'not a fee role', 'no pending grid',
    'not the fee guardian or sentinel', 'not the fee guardian', 'invalid fee account role', 'unknown operation',
    'reserved operation', 'symbol taken', 'unknown asset', 'fee batch failed',
  ])
    assert.ok(seen.has('rejected: ' + verdict), verdict);
  assert.ok(v.cases.some((c) => c.expect.verdicts.some((r) => r.feeKept)));
});

test('encodings, fees, checkRate and the tickers digest', () => {
  for (const e of v.encodings) {
    const run = () => toJson(decode(fromHex(e.hex), decodeOptions(checkRules(e.rules), e.height)).op);
    if (e.ok) assert.deepEqual(run(), e.op, e.name);
    else assert.throws(run, { message: e.error }, e.name);
  }
  const ok = new Set(v.encodings.filter((e) => e.ok).map((e) => e.name));
  for (const n of ['FEE_RATE', 'FEE_ADMIN cancel', 'FEE_ADMIN freeze', 'FEE_ADMIN setOperator', 'FEE_ADMIN setGuardian', 'FEE_ADMIN setSentinel']) assert.ok(ok.has(n), n);
  assert.equal(ok.size, 6);
  for (const f of v.fees.filter((f) => f.kind !== 'target')) {
    const op = f.kind === 'inscribe' ? { kind: 'inscribe', contentType: 'text/plain', content: '0x01' } : { kind: f.kind, symbol: f.symbol };
    assert.equal(String(fee(op, BigInt(f.rate))), f.fee);
  }
  for (const r of v.checkRate) assert.equal(checkRate(BigInt(r.rate)), r.ok);
  assert.equal(v.tickersDigest, TICKERS_DIGEST);
});

test('randomHistory gives the Python property run accepted wallet operations', () => {
  const r = randomHistory(7, { blocks: 1200 });
  assert.ok(r.wallet.length > 10);
  const x = replay(r);
  for (const w of r.wallet)
    assert.equal(x.state().journal.find((e) => e.height === w.height && e.index === w.index)?.verdict, 'accepted');
});

test('snapshot format 2 carries the fee state strictly; format 1 is refused', () => {
  const c = v.cases.find((x) => x.name.startsWith('windows'));
  const x = replay(c);
  const s = x.state(), snap = snapshot(s, c.genesis);
  assert.equal(snap.format, 2);
  assert.equal(snap.fees.current.rate, '12000000000');
  assert.deepEqual(snapshotState(snap, c.genesis).fees, s.fees);
  const { fees, ...withoutFees } = snap;
  for (const bad of [
    { ...snap, format: 1 },
    withoutFees,
    { ...snap, fees: { ...fees, current: { ...fees.current, rate: 12_000_000_000 } } },
    { ...snap, fees: { ...fees, current: { ...fees.current, rate: '012000000000' } } },
    { ...snap, fees: { ...fees, extra: null } },
    { ...snap, fees: { ...fees, sentinel: fees.guardian } },
    { ...snap, fees: { ...fees, nextGrid: 0 } },
    { ...snap, fees: { ...fees, pending: { ...fees.current, id: fees.nextGrid - 1, effective: s.height } } },
    { ...snap, fees: { ...fees, current: { ...fees.current, rate: '12340000000' } } },
  ])
    assert.throws(() => snapshotState(bad, c.genesis), JSON.stringify(bad.fees ?? null).slice(0, 80));
  // A legacy state has no fee state, and its snapshot says so.
  const legacy = replay(v.cases[0]).state();
  assert.equal(snapshot(legacy, v.cases[0].genesis).fees, null);
  assert.equal(verifiedFeeSchedule({ state: legacy }), null);
  assert.deepEqual(verifiedFeeSchedule({ state: s }), { current: s.fees.current, previous: s.fees.previous, pending: s.fees.pending, height: s.height, hash: s.hash });
});
